mapper.select:
SELECT b.guid AS parentguid, f$.guid AS subguid, (select description from MA_CLASS m where m.guid = f$.classguid) AS description, f$. ID AS subid, f$. NAME AS NAME, F$. SPECIFICATION AS SPECIFICATION, f$.classification AS classification, f$.revisionid || '.' || f$.iterationid AS revisionid, (select MCD.TITLE from MA_CODE_DETAIL MCD where MCD.DELFLAG = 'N' AND MCD.GUID = (select F_000072 from ITEM_1 ITEM1 where ITEM1.FOUNDATIONFK= f$.guid)) AS sourcetype, f$.status AS status FROM ITEM_0 f$, BOMVIEW_0 A, BOMSTRUCTURE_0 s, ITEM_0 b, bi_bom_template T, ITEM_1 F$1 WHERE f$.guid = A .end1 AND A .guid = s.viewfk AND A .templateid = T . ID AND b.masterfk = s.end2$master AND ( 1 = 1 AND f$.guid = F$1.foundationfk (+) ) AND f$.latestrevision LIKE 'm%' AND A . NAME = 'BOM'
AND b.guid = #{guid}
ORDER BY f$. ID, f$.revisionid
